{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated-run testing is undocumented; silence does not establish whether it occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score provides no evidence of consistency across runs."
        }
      ],
      "instrument_review": "Construction and scoring are specified for a narrow puzzle comparison. Reporting lacks repeated-run evidence, so score consistency and the reliability of comparisons remain unestablished."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated-run testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "Without repeated runs, the findings establish neither stability nor instability."
        }
      ],
      "instrument_review": "The scoring supports describing the single observed puzzle result. The documented absence of repetition leaves consistency untested and limits confidence in comparisons based on that score."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The evaluation was repeated with the stated conditions held constant."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The two-percentage-point range meets the report's stated stability criterion."
        }
      ],
      "instrument_review": "Repeated evaluations support consistency under the specified conditions and definition of stability. This evidence supports the narrow puzzle use; consistency across other inputs, settings, or tasks is not established."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The developers examined repeated scores under unchanged stated conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the report's maximum of two percentage points for stability."
        }
      ],
      "instrument_review": "The repeated evaluations document substantial inconsistency under fixed conditions. Reporting the 70% result alone would not adequately represent the observed variation, which limits dependable system comparisons."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not document repeated-run testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added documentation supplies no evidence about score consistency."
        }
      ],
      "instrument_review": "Installation guidance explains setup, but does not establish repeated execution or stable scores. The narrow scoring interpretation remains supported, while consistency and comparability across runs remain undocumented."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A achieved the higher result on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The evidence does not establish comparative intelligence across domains."
        }
      ],
      "instrument_review": "The evaluated tasks and exact scoring match the stated narrow use. Fixed instructions support comparison, but repeated-run consistency and other resource conditions are unspecified. Broader interpretations exceed the supplied evidence."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported results show better performance by A on these puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The intended broad use does not supply evidence of performance across domains."
        }
      ],
      "instrument_review": "The stated selection purpose exceeds what the test construction and findings support. Exact scoring and fixed instructions support the observed puzzle comparison, but cross-domain evidence, repeated-run consistency, and complete comparison conditions are missing."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial evidence alone does not establish improved decisions in actual workshop use."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "Random allocation, blinded correctness checks, and a reported difference interval of 12 to 28 percentage points support better correctness with A in the studied conditions."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved correctness does not establish an improvement in an unmeasured safety outcome."
        }
      ],
      "instrument_review": "The later preregistered, randomized trial supplies evidence relevant to choosing assistance for correct decisions in this workshop. Blinded checking and reported uncertainty strengthen interpretation. Results do not establish safety benefits, time benefits, or performance in other workshops; repeated-study consistency is unspecified."
    }
  ],
  "closing_note": "No instructions were unclear. Missing evidence was distinguished from explicit conflicting evidence."
}
